package cl.bolsillo.app;
import android.app.*;import android.widget.*;import org.json.*;import java.time.*;import java.util.*;

final class Forms {
 static void pickDate(MainActivity a,EditText field,LocalDate date){CalendarSheet.show(a,field,date);}
 static final class Form {
  final MainActivity a;final LinearLayout box;final Dialog dialog; int advancedStart=-1;
  void advanced(){advancedStart=box.getChildCount();}
  void collapseAdvanced(){collapseAdvanced("Más opciones");}
  void collapseAdvanced(String label){if(advancedStart<0||advancedStart==box.getChildCount())return;java.util.List<android.view.View> views=new java.util.ArrayList<>();for(int i=advancedStart;i<box.getChildCount();i++){android.view.View v=box.getChildAt(i);v.setVisibility(8);views.add(v);}Button toggle=Glass.button(a,"Más opciones");toggle.setText(label);box.addView(toggle,advancedStart);toggle.setOnClickListener(v->{boolean open=views.get(0).getVisibility()==8;for(android.view.View item:views)item.setVisibility(open?0:8);toggle.setText(open?"Menos opciones":label);});advancedStart=-1;}
  Form(MainActivity a,String title){this.a=a;box=NativeSettings.panel(a,title);dialog=NativeSettings.display(a,box);}
  void note(String s){box.addView(Glass.text(a,s,14,false));}
  EditText field(String label,String value,boolean number){box.addView(Glass.text(a,label,13,true));EditText e=NativeSettings.input(a,box,label,value);e.setHint("");String normalized=BankNotificationParser.normalize(label);if(number&&(normalized.contains("monto")||normalized.contains("saldo")||normalized.contains("clp")||normalized.contains("limite mensual")||normalized.contains("cupo")||normalized.contains("interes realmente")))MoneyInput.apply(a,box,e);if(number)e.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_SIGNED);if(!number&&label.toLowerCase(java.util.Locale.ROOT).contains("fecha")){DateInput.apply(a,e,label);e.setFocusable(false);e.setOnClickListener(v->{java.time.LocalDate date;try{date=java.time.LocalDate.parse(e.getText().toString());}catch(Exception ignored){date=java.time.LocalDate.parse(Ledger.today());}pickDate(a,e,date);});if(label.toLowerCase(java.util.Locale.ROOT).contains("opcional")){e.setOnLongClickListener(v->{e.setText("");return true;});}}return e;}
  AutoCompleteTextView conceptField(String label,String value,String type)throws Exception{box.addView(Glass.text(a,label,13,true));AutoCompleteTextView field=NativeSettings.conceptInput(a,box,label,value,ConceptCatalog.suggestions(a.data,type));field.setHint("");return field;}
  void bindConcept(AutoCompleteTextView field,Pick category,String type){field.setOnItemClickListener((parent,view,position,id)->a.attempt(()->{String preferred=ConceptCatalog.preferredCategory(LocalData.read(a),type,value(field));if(!preferred.isEmpty())category.setId(preferred);}));}
  Switch toggle(String text,boolean on){Switch v=new Switch(a);Controls.style(v);v.setText(text);v.setTypeface(Glass.font(a,500));v.setChecked(on);v.setMinHeight(a.dp(52));box.addView(v);return v;}
  Spinner select(String label,List<String> names,int chosen){TextView heading=Glass.text(a,label,13,true);heading.setVisibility(android.view.View.GONE);box.addView(heading);Spinner s=new GlassSpinner(a);s.setContentDescription(label);ArrayAdapter<String> adapter=new ArrayAdapter<>(a,android.R.layout.simple_spinner_item,names);adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);s.setAdapter(adapter);s.setSelection(Math.max(0,chosen));s.setMinimumHeight(a.dp(70));LinearLayout.LayoutParams layout=new LinearLayout.LayoutParams(-1,-2);layout.topMargin=a.dp(4);layout.bottomMargin=a.dp(10);box.addView(s,layout);return s;}
  void action(String label,MainActivity.Work w){NativeSettings.action(a,box,label,()->a.attempt(w));}
  void save(String label,MainActivity.Work w){Runnable commit=()->a.attempt(()->{w.run();dialog.dismiss();a.render();});if(dialog instanceof SheetDialog)((SheetDialog)dialog).actions(label,commit);else{action(label,()->{w.run();dialog.dismiss();a.render();});action("Cancelar",dialog::dismiss);}}
 }
 static final class Pick {List<String> ids=new ArrayList<>(),names=new ArrayList<>();Spinner spinner;
  Pick(Form f,String label,String key,String kind,String selected)throws Exception{JSONArray list=f.a.data.getJSONArray(key);for(int i=0;i<list.length();i++){JSONObject o=list.getJSONObject(i);if(o.optBoolean("archived")&&!o.optString("id").equals(selected))continue;if(!kind.isEmpty()&&!o.optString("type").equals(kind))continue;ids.add(o.getString("id"));names.add(o.optString("name"));}spinner=f.select(label,names,ids.indexOf(selected));if(key.equals("categories")){TextView create=Modern.text(f.a,"＋ Crear categoría",13,Glass.accent(f.a),true);create.setPadding(f.a.dp(8),f.a.dp(5),0,f.a.dp(10));f.box.addView(create);Modern.press(create,()->{LinearLayout panel=NativeSettings.panel(f.a,"Nueva categoría");Dialog dialog=NativeSettings.display(f.a,panel);EditText name=NativeSettings.input(f.a,panel,"Nombre de la categoría","");NativeSettings.action(f.a,panel,"Crear y seleccionar",()->f.a.attempt(()->{String[] chosen={""};LocalData.change(f.a,d->chosen[0]=ConceptCatalog.ensureCategory(d,kind,Forms.value(name)).getString("id"));JSONObject cat=Ledger.find(LocalData.read(f.a).getJSONArray("categories"),chosen[0]);if(!ids.contains(chosen[0])){ids.add(chosen[0]);names.add(cat.getString("name"));ArrayAdapter<String> adapter=new ArrayAdapter<>(f.a,android.R.layout.simple_spinner_item,names);adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);spinner.setAdapter(adapter);}setId(chosen[0]);dialog.dismiss();}));NativeSettings.action(f.a,panel,"Cancelar",dialog::dismiss);});}}
  void setId(String selected){int index=ids.indexOf(selected);if(index>=0)spinner.setSelection(index);}
  void requireChoice(String selected){if(ids.contains(selected))return;ids.add(0,"");names.add(0,"Elegir cuenta");ArrayAdapter<String> adapter=new ArrayAdapter<>(spinner.getContext(),android.R.layout.simple_spinner_item,names);adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);spinner.setAdapter(adapter);spinner.setSelection(0);}
  String id()throws Exception{int position=spinner.getSelectedItemPosition();Ledger.require(position>=0&&position<ids.size()&&!ids.get(position).isEmpty(),"Falta una cuenta o categoría");return ids.get(position);}
 }
 static String value(EditText e){return e.getText().toString().trim();}
 static long amount(EditText e,boolean signed)throws Exception{try{long n=Long.parseLong(value(e));Ledger.require(n<=Ledger.MAX&&n>=(signed?-Ledger.MAX:1),"Monto fuera de rango");return n;}catch(NumberFormatException ex){throw new Exception("Escribe pesos enteros sin puntos ni comas");}}
 static String accountType(String t){switch(t){case "bank":return "Cuenta / débito";case "credit":return "Tarjeta de crédito";case "savings":return "Ahorro";case "investment":return "Inversión";default:return "Efectivo";}}
 static void accountMenu(MainActivity a,JSONObject item){NativeSettings.choose(a,item.optString("name"),Arrays.asList("Editar cuenta y saldo inicial","Conciliar saldo actual","Ver movimientos","Rendimientos de ahorro"),n->a.attempt(()->{if(n==0)account(a,item);if(n==1)reconcile(a,item);if(n==2){a.tab="Movimientos";a.accountFilter=item.getString("id");a.render();}if(n==3)Extras.yield(a,item);}));}
 static void account(MainActivity host,JSONObject existing)throws Exception{
  JSONObject a=existing==null?Ledger.account(Ledger.id(),"","bank","other"):new JSONObject(existing.toString());Form f=new Form(host,existing==null?"Nueva cuenta":"Editar cuenta");EditText name=f.field("Nombre",a.optString("name"),false),opening=f.field("Saldo inicial en CLP",a.optString("opening","0"),true);List<String> types=Arrays.asList("bank","cash","credit","savings","investment");Spinner type=f.select("Tipo",Arrays.asList("Cuenta / débito","Efectivo","Tarjeta de crédito","Ahorro","Inversión"),types.indexOf(a.optString("type")));List<String> banks=BankCatalog.ids(),bankNames=BankCatalog.names();String institution=a.optString("institution","other");if(!banks.contains(institution)){banks.add(institution);bankNames.add(institution);}Spinner bank=f.select("Institución",bankNames,banks.indexOf(institution));EditText limit=f.field("Cupo de crédito (0 si no aplica)",a.optString("limit","0"),true),closing=f.field("Día de cierre",a.optString("closingDay","1"),true),due=f.field("Día de pago",a.optString("dueDay","5"),true);Switch included=f.toggle("Incluir en patrimonio",a.optBoolean("included",true)),archived=f.toggle("Archivar cuenta",a.optBoolean("archived"));f.note("El saldo inicial es el punto de partida. Para ajustar el saldo de hoy usa Conciliar saldo actual.");
  f.save("Guardar cuenta",()->{int c=Integer.parseInt(value(closing)),d=Integer.parseInt(value(due));Ledger.require(c>=1&&c<=31&&d>=1&&d<=31,"Los días deben estar entre 1 y 31");long l=amount(limit,true);Ledger.require(l>=0,"Cupo inválido");a.put("name",value(name)).put("opening",amount(opening,true)).put("type",types.get(type.getSelectedItemPosition())).put("institution",banks.get(bank.getSelectedItemPosition())).put("limit",l).put("closingDay",c).put("dueDay",d).put("included",included.isChecked()).put("archived",archived.isChecked());LocalData.upsert(host,"accounts",a);});
 }
 static void reconcile(MainActivity host,JSONObject a)throws Exception{Form f=new Form(host,"Conciliar · "+a.getString("name"));long current=Ledger.balances(host.data,Ledger.today()).get(a.getString("id"));f.note("Saldo registrado: "+host.money(current)+". Se creará un ajuste identificado y excluido de los informes.");EditText actual=f.field("Saldo actual que ves en el banco",String.valueOf(current),true);f.save("Guardar ajuste de saldo",()->{long wanted=amount(actual,true);LocalData.change(host,d->{long diff=wanted-Ledger.balances(d,Ledger.today()).get(a.getString("id"));if(diff==0)return;String type=diff>0?"income":"expense",cat=type.equals("income")?"income-reconcile":"expense-reconcile";if(Ledger.find(d.getJSONArray("categories"),cat)==null)d.getJSONArray("categories").put(new JSONObject().put("id",cat).put("name","Ajuste de saldo").put("type",type).put("emoji","").put("color","#64748b").put("archived",false));JSONObject t=NativeSync.transaction(type,Math.abs(diff),a.getString("id"),"",cat,"Conciliación de saldo","manual","");t.put("excluded",true);d.getJSONArray("transactions").put(t);});});}
 static void chooseTransaction(MainActivity a){NativeSettings.choose(a,"Registrar",Arrays.asList("Gasto","Ingreso","Transferencia entre cuentas"),n->a.attempt(()->transaction(a,null,new String[]{"expense","income","transfer"}[n])));}
 static void details(MainActivity a,JSONObject t)throws Exception{TransactionDetail.show(a,t);}
 static void transactionMenu(MainActivity a,JSONObject t){if(t.optString("type").equals("repayment")){List<String> repaymentOptions=new ArrayList<>(Arrays.asList("Ver detalle","Ver personas"));if(t.has("linkedIncomeCategory"))repaymentOptions.add("Desvincular ingreso");repaymentOptions.add("Eliminar cobro");NativeSettings.choose(a,"Cobro",repaymentOptions,n->a.attempt(()->{String choice=repaymentOptions.get(n);if(choice.equals("Ver detalle"))details(a,t);else if(choice.startsWith("Ver"))a.navigate("Personas");else if(choice.startsWith("Desvincular"))a.confirm("Desvincular ingreso","Volverá a figurar como ingreso y la deuda quedará pendiente. El saldo no cambiará.",()->LocalData.change(a,d->Finance.unlinkIncome(d,t.getString("id"))));else a.confirm("Eliminar cobro","La deuda quedará pendiente y este ingreso saldrá del saldo.",()->LocalData.remove(a,"transactions",t.getString("id")));}));return;}if(t.optString("type").equals("loan")){NativeSettings.choose(a,"Préstamo",Arrays.asList("Ver detalle","Ver personas","Eliminar préstamo"),n->a.attempt(()->{if(n==0)details(a,t);else if(n==1)a.navigate("Personas");else a.confirm("Eliminar préstamo","Se recalculará el saldo y lo pendiente de cobro.",()->LocalData.remove(a,"transactions",t.getString("id")));}));return;}List<String> options=new ArrayList<>();options.add("Ver detalle");if(t.optString("status").equals("pending"))options.add("Confirmar y actualizar saldo");options.add("Editar movimiento");if(t.optString("type").equals("income")&&t.optString("status").equals("posted")&&!t.optBoolean("excluded"))options.add("Asignar ingreso a una deuda");if(!t.optString("type").equals("repayment"))options.add("Duplicar como nuevo");options.add("Eliminar movimiento");NativeSettings.choose(a,"Movimiento",options,n->a.attempt(()->{String choice=options.get(n);if(choice.equals("Ver detalle"))details(a,t);else if(choice.startsWith("Confirmar")){LocalData.upsert(a,"transactions",new JSONObject(t.toString()).put("status","posted"));a.render();}else if(choice.startsWith("Editar")){if(WorkScreen.matches(a.data,t))WorkScreen.edit(a,t);else transaction(a,t,t.optString("type"));}else if(choice.startsWith("Asignar"))PeopleScreen.linkIncome(a,t,null);else if(choice.startsWith("Duplicar")){JSONObject copy=new JSONObject(t.toString()).put("id",Ledger.id()).put("date",Ledger.today()).put("source","manual").put("sourceId","").put("installments",1).put("installment",0).put("installmentGroup","").put("shares",new JSONArray()).put("receivable","");transaction(a,copy,t.optString("type"));}else a.confirm("Eliminar movimiento","El saldo se recalculará. Se elimina solo este movimiento.",()->LocalData.remove(a,"transactions",t.getString("id")));}));}
 static void transaction(MainActivity a,JSONObject existing,String kind)throws Exception{
  if(kind.equals("repayment")||kind.equals("loan")){Form f=new Form(a,"Cobro compartido");f.note("Gestiona los cobros desde Más → Gastos compartidos. Puedes eliminar un cobro desde el detalle del movimiento.");f.save("Cerrar",()->{});return;}
  Ledger.require(Arrays.asList("expense","income","transfer").contains(kind),"Tipo inválido");Form f=new Form(a,existing==null?(kind.equals("expense")?"Nuevo gasto":kind.equals("income")?"Nuevo ingreso":"Mover entre cuentas"):"Editar movimiento");JSONObject old=existing==null?new JSONObject():existing;EditText amt=f.field("Monto en pesos",old.optString("amount",""),true);AutoCompleteTextView note=f.conceptField("Comercio o descripción",old.optString("note"),kind);Pick from=new Pick(f,kind.equals("income")?"Cuenta que recibe":"Cuenta de origen","accounts","",old.optString("account"));Pick target=new Pick(f,kind.equals("transfer")?"Cuenta de destino":"Categoría",kind.equals("transfer")?"accounts":"categories",kind.equals("transfer")?"":kind,old.optString(kind.equals("transfer")?"to":"category"));if(!kind.equals("transfer"))f.bindConcept(note,target,kind);f.advanced();EditText date=f.field("Fecha",old.optString("date",Ledger.today()),false);EditText tags=f.field("Etiquetas",old.optString("tags"),false);Switch pending=f.toggle("Pendiente: no afecta el saldo",old.optString("status").equals("pending")),excluded=f.toggle("Excluir de informes",old.optBoolean("excluded"));SharesEditor parts=kind.equals("expense")?new SharesEditor(f,old.optJSONArray("shares")):null;EditText installments=null;if(kind.equals("expense")&&existing==null){installments=f.field("Cuotas (1 para pago único)","1",true);f.note("Las cuotas dividen el total sin perder pesos. En crédito, toda la deuda queda comprometida desde la compra.");}final EditText countField=installments;f.collapseAdvanced();
  f.save("Guardar movimiento",()->{long n=amount(amt,false);LocalDate parsed=LocalDate.parse(value(date));JSONObject t=existing==null?NativeSync.transaction(kind,n,from.id(),kind.equals("transfer")?target.id():"",kind.equals("transfer")?"":target.id(),value(note),"manual",""):new JSONObject(existing.toString());t.put("amount",n).put("account",from.id()).put("to",kind.equals("transfer")?target.id():"").put("category",kind.equals("transfer")?"":target.id()).put("note",value(note)).put("date",parsed.toString()).put("tags",value(tags)).put("status",pending.isChecked()?"pending":"posted").put("excluded",excluded.isChecked());int count=countField==null?1:Integer.parseInt(value(countField));Ledger.require(count>=1&&count<=120&&n>=count,"Revisa las cuotas: 1 a 120, mínimo $1 cada una");if(parts!=null&&parts.parts.length()>0){Ledger.require(count==1&&parts.total()<=n,"Revisa las partes y las cuotas");t.put("shares",parts.value());}if(count==1)LocalData.upsert(a,"transactions",t);else LocalData.change(a,d->{String group=Ledger.id();for(int i=0;i<count;i++)d.getJSONArray("transactions").put(new JSONObject(t.toString()).put("id",Ledger.id()).put("amount",n/count+(i<n%count?1:0)).put("date",parsed.plusMonths(i).toString()).put("installmentGroup",group).put("installment",i+1).put("installments",count));});});
 }
 static void budget(MainActivity a)throws Exception{Form f=new Form(a,"Presupuesto mensual");Pick cat=new Pick(f,"Categoría","categories","expense","");EditText amt=f.field("Límite mensual en CLP","",true);f.save("Guardar presupuesto",()->LocalData.change(a,d->{JSONArray list=d.getJSONArray("budgets");for(int i=list.length()-1;i>=0;i--)if(list.getJSONObject(i).optString("category").equals(cat.id()))list.remove(i);list.put(new JSONObject().put("id",Ledger.id()).put("category",cat.id()).put("amount",amount(amt,false)));}));}
 static void budgetMenu(MainActivity a,JSONObject b)throws Exception{Form f=new Form(a,"Presupuesto · "+a.name("categories",b.getString("category")));EditText amt=f.field("Límite mensual",b.optString("amount"),true);f.action("Eliminar presupuesto",()->a.confirm("Eliminar presupuesto","Los movimientos se conservarán.",()->{LocalData.remove(a,"budgets",b.getString("id"));f.dialog.dismiss();}));f.save("Guardar",()->LocalData.upsert(a,"budgets",new JSONObject(b.toString()).put("amount",amount(amt,false))));}
 static void goal(MainActivity a,JSONObject old)throws Exception{Form f=new Form(a,"Meta de ahorro");JSONObject g=old==null?new JSONObject():old;EditText name=f.field("Nombre",g.optString("name"),false),target=f.field("Objetivo en CLP",g.optString("target"),true),deadline=f.field("Fecha objetivo opcional",g.optString("deadline"),false);JSONArray selected=g.optJSONArray("accounts");List<CheckBox> checks=new ArrayList<>();JSONArray accounts=a.data.getJSONArray("accounts");for(int i=0;i<accounts.length();i++){JSONObject ac=accounts.getJSONObject(i);CheckBox cb=new CheckBox(a);Controls.style(cb);cb.setText(ac.getString("name"));if(selected!=null)for(int j=0;j<selected.length();j++)if(selected.getString(j).equals(ac.getString("id")))cb.setChecked(true);f.box.addView(cb);checks.add(cb);}f.note("La meta usa el saldo de las cuentas elegidas; no suma dinero adicional al patrimonio.");if(old!=null)f.action("Eliminar meta",()->a.confirm("Eliminar meta","Las cuentas se conservan.",()->{LocalData.remove(a,"goals",g.getString("id"));f.dialog.dismiss();}));f.save("Guardar meta",()->{Ledger.require(!value(name).isEmpty(),"Escribe un nombre");JSONArray ids=new JSONArray();for(int i=0;i<checks.size();i++)if(checks.get(i).isChecked())ids.put(accounts.getJSONObject(i).getString("id"));Ledger.require(ids.length()>0,"Selecciona una cuenta");LocalData.upsert(a,"goals",new JSONObject().put("id",g.optString("id",Ledger.id())).put("name",value(name)).put("target",amount(target,false)).put("deadline",value(deadline)).put("accounts",ids));});}
 static void recurring(MainActivity a){NativeSettings.choose(a,"Tipo recurrente",Arrays.asList("Gasto / suscripción","Ingreso","Transferencia"),n->a.attempt(()->{String kind=new String[]{"expense","income","transfer"}[n];Form f=new Form(a,"Programar movimiento");AutoCompleteTextView name=f.conceptField("Nombre","",kind);EditText amt=f.field("Monto CLP","",true),date=f.field("Próxima fecha",Ledger.today(),false);Pick from=new Pick(f,"Cuenta","accounts","","");Pick to=new Pick(f,kind.equals("transfer")?"Destino":"Categoría",kind.equals("transfer")?"accounts":"categories",kind.equals("transfer")?"":kind,"");if(!kind.equals("transfer"))f.bindConcept(name,to,kind);Spinner frequency=f.select("Frecuencia",Arrays.asList("Mensual","Semanal","Anual"),0);Switch auto=f.toggle("Registrar automáticamente al abrir",false);f.save("Guardar programación",()->{Ledger.require(!value(name).isEmpty(),"Falta nombre");LocalData.upsert(a,"recurring",new JSONObject().put("id",Ledger.id()).put("name",value(name)).put("type",kind).put("amount",amount(amt,false)).put("account",from.id()).put("to",kind.equals("transfer")?to.id():"").put("category",kind.equals("transfer")?"":to.id()).put("next",LocalDate.parse(value(date)).toString()).put("frequency",new String[]{"monthly","weekly","yearly"}[frequency.getSelectedItemPosition()]).put("active",true).put("automatic",auto.isChecked()).put("anchorDay",LocalDate.parse(value(date)).getDayOfMonth()).put("shares",new JSONArray()).put("service",""));});}));}
 static void recurringMenu(MainActivity a,JSONObject r){List<String> choices=new ArrayList<>(Arrays.asList("Registrar próximo vencimiento","Pausar / reactivar","Editar monto y próxima fecha"));boolean expense=r.optString("type").equals("expense");if(expense)choices.add("Repartir este pago");choices.add("Eliminar programación");NativeSettings.choose(a,r.optString("name"),choices,n->a.attempt(()->{String choice=choices.get(n);if(choice.equals("Eliminar programación")){a.confirm("Eliminar programación","Los movimientos ya registrados se conservan.",()->LocalData.remove(a,"recurring",r.getString("id")));return;}if(choice.equals("Repartir este pago")){Form f=new Form(a,"Compartir · "+r.optString("name"));SharesEditor parts=new SharesEditor(f,r.optJSONArray("shares"));f.save("Guardar reparto",()->{Ledger.require(parts.total()<=r.getLong("amount"),"Las partes superan el cobro");LocalData.upsert(a,"recurring",new JSONObject(r.toString()).put("shares",parts.value()));});return;}if(choice.startsWith("Editar")){Form f=new Form(a,"Editar programación");EditText amt=f.field("Monto",r.optString("amount"),true),date=f.field("Próxima fecha",r.optString("next"),false);Switch auto=f.toggle("Registro automático al abrir",r.optBoolean("automatic"));Switch match=f.toggle("Avanzar al recibir su notificación",r.optBoolean("matchNotifications"));f.save("Guardar",()->{long amount=amount(amt,false);JSONArray shares=r.optJSONArray("shares");long parts=0;if(shares!=null)for(int i=0;i<shares.length();i++)parts+=shares.getJSONObject(i).getLong("amount");Ledger.require(parts<=amount,"El reparto supera el cobro");LocalData.upsert(a,"recurring",new JSONObject(r.toString()).put("amount",amount).put("next",LocalDate.parse(value(date)).toString()).put("anchorDay",LocalDate.parse(value(date)).getDayOfMonth()).put("automatic",auto.isChecked()).put("matchNotifications",match.isChecked()&&!auto.isChecked()));});return;}LocalData.change(a,d->{JSONObject current=Ledger.find(d.getJSONArray("recurring"),r.getString("id"));Ledger.require(current!=null,"Programación inexistente");if(choice.startsWith("Pausar"))current.put("active",!current.optBoolean("active"));else{String id="auto-"+current.getString("id")+"-"+current.getString("next");if(Ledger.find(d.getJSONArray("transactions"),id)==null){JSONObject t=NativeSync.transaction(current.getString("type"),current.getLong("amount"),current.getString("account"),current.optString("to"),current.optString("category"),current.getString("name"),"manual","");t.put("id",id).put("date",current.getString("next")).put("shares",current.optJSONArray("shares")==null?new JSONArray():new JSONArray(current.getJSONArray("shares").toString()));d.getJSONArray("transactions").put(t);}current.put("next",Ledger.next(current.getString("next"),current.getString("frequency"),current.optInt("anchorDay")));}});a.render();}));}
}


